import { sql } from 'drizzle-orm';
import {
	check,
	date,
	index,
	integer,
	jsonb,
	numeric,
	pgTable,
	primaryKey,
	text,
	timestamp,
	foreignKey,
	unique,
	uuid
} from 'drizzle-orm/pg-core';
import { users } from '../auth/index.ts';
import { foods } from '../catalog/index.ts';
import type { EntryNutrients, FoodSnapshot, SnapshotUnit } from '../../../shared/diary-types.ts';

// RLS policies and grants live in hand-written migrations under drizzle/.
export const diaryEntries = pgTable(
	'diary_entries',
	{
		// May be generated by the client so retries and offline creates are idempotent.
		id: uuid('id').primaryKey(),
		userId: uuid('user_id')
			.notNull()
			.references(() => users.id, { onDelete: 'cascade' }),
		// The diary day and meal the person chose, not the upload time.
		localDate: date('local_date', { mode: 'string' }).notNull(),
		meal: text('meal', { enum: ['breakfast', 'lunch', 'dinner', 'snacks'] }).notNull(),
		// IANA zone captured when the entry was made.
		zone: text('zone').notNull(),
		eatenAt: timestamp('eaten_at', { withTimezone: true }),
		kind: text('kind', { enum: ['food', 'quick'] }).notNull(),
		// Optional link to the catalog; the snapshot below is what counts.
		foodId: uuid('food_id').references(() => foods.id, { onDelete: 'set null' }),
		food: jsonb('food').$type<FoodSnapshot>(),
		amount: numeric('amount', { precision: 12, scale: 4, mode: 'number' }),
		unit: jsonb('unit').$type<SnapshotUnit>(),
		description: text('description'),
		nutrients: jsonb('nutrients').$type<EntryNutrients>().notNull(),
		energyKcal: numeric('energy_kcal', {
			precision: 12,
			scale: 4,
			mode: 'number'
		}).generatedAlwaysAs(sql`(nutrients -> 'energy_kcal' ->> 'value')::numeric`),
		revision: integer('revision').notNull().default(1),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		// Trash: hidden from the diary, restorable for 30 days, then purged.
		deletedAt: timestamp('deleted_at', { withTimezone: true })
	},
	(t) => [
		check('diary_entries_meal_valid', sql`${t.meal} in ('breakfast', 'lunch', 'dinner', 'snacks')`),
		check('diary_entries_kind_valid', sql`${t.kind} in ('food', 'quick')`),
		check(
			'diary_entries_shape',
			sql`(${t.kind} = 'food' and ${t.food} is not null and ${t.amount} > 0 and ${t.unit} is not null)
				or (${t.kind} = 'quick' and ${t.food} is null and ${t.amount} is null and ${t.unit} is null
					and ${t.foodId} is null and (${t.nutrients} -> 'energy_kcal') is not null)`
		),
		check(
			'diary_entries_description_length',
			sql`${t.description} is null or char_length(${t.description}) between 1 and 200`
		),
		check('diary_entries_nutrients_object', sql`jsonb_typeof(${t.nutrients}) = 'object'`),
		check(
			'diary_entries_energy_non_negative',
			sql`${t.energyKcal} is null or ${t.energyKcal} >= 0`
		),
		check('diary_entries_zone_format', sql`${t.zone} ~ '^[A-Za-z_]+(/[A-Za-z0-9_+-]+)*$'`),
		check('diary_entries_revision_positive', sql`${t.revision} >= 1`),
		index('diary_entries_user_date_idx')
			.on(t.userId, t.localDate)
			.where(sql`${t.deletedAt} is null`),
		index('diary_entries_user_food_idx').on(t.userId, t.foodId, t.createdAt)
	]
);

// Days the person marked complete (only complete days at or under budget count as "under" in the calendar).
export const dayCompletions = pgTable(
	'day_completions',
	{
		userId: uuid('user_id')
			.notNull()
			.references(() => users.id, { onDelete: 'cascade' }),
		localDate: date('local_date', { mode: 'string' }).notNull(),
		source: text('source', { enum: ['manual', 'loseit'] })
			.notNull()
			.default('manual'),
		completedAt: timestamp('completed_at', { withTimezone: true }).notNull().defaultNow()
	},
	(t) => [
		primaryKey({ columns: [t.userId, t.localDate] }),
		check('day_completions_source_valid', sql`${t.source} in ('manual', 'loseit')`)
	]
);

// Minimal markers for trash rows purged after 30 days (diary and body readings), so a late offline retry of the
// same client ID is recognised instead of recreating the deleted record. Written only by app_purge_trash().
export const purgedRecords = pgTable(
	'purged_records',
	{
		id: uuid('id').primaryKey(),
		userId: uuid('user_id')
			.notNull()
			.references(() => users.id, { onDelete: 'cascade' }),
		kind: text('kind', { enum: ['diary', 'weight', 'water', 'activity'] }).notNull(),
		purgedAt: timestamp('purged_at', { withTimezone: true }).notNull().defaultNow()
	},
	(t) => [
		check('purged_records_kind_valid', sql`${t.kind} in ('diary', 'weight', 'water', 'activity')`)
	]
);

// Saved meals: a named list of items, each with its own snapshot like a diary entry (docs/design.md, "Diary and
// logging rules"). Logging one creates ordinary entries; refreshing items to current food values is explicit.
export const savedMeals = pgTable(
	'saved_meals',
	{
		id: uuid('id').primaryKey(),
		userId: uuid('user_id')
			.notNull()
			.references(() => users.id, { onDelete: 'cascade' }),
		name: text('name').notNull(),
		revision: integer('revision').notNull().default(1),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow()
	},
	(t) => [
		unique('saved_meals_id_user').on(t.id, t.userId),
		check('saved_meals_name_length', sql`char_length(${t.name}) between 1 and 120`),
		check('saved_meals_revision_positive', sql`${t.revision} >= 1`),
		index('saved_meals_user_idx').on(t.userId, t.updatedAt)
	]
);

export const savedMealItems = pgTable(
	'saved_meal_items',
	{
		id: uuid('id').primaryKey(),
		savedMealId: uuid('saved_meal_id').notNull(),
		// Must match the meal's owner (composite foreign key), so an item can never hang off someone else's meal.
		userId: uuid('user_id').notNull(),
		position: integer('position').notNull(),
		kind: text('kind', { enum: ['food', 'quick'] }).notNull(),
		foodId: uuid('food_id').references(() => foods.id, { onDelete: 'set null' }),
		food: jsonb('food').$type<FoodSnapshot>(),
		amount: numeric('amount', { precision: 12, scale: 4, mode: 'number' }),
		unit: jsonb('unit').$type<SnapshotUnit>(),
		description: text('description'),
		nutrients: jsonb('nutrients').$type<EntryNutrients>().notNull()
	},
	(t) => [
		foreignKey({
			name: 'saved_meal_items_meal_owner',
			columns: [t.savedMealId, t.userId],
			foreignColumns: [savedMeals.id, savedMeals.userId]
		}).onDelete('cascade'),
		unique('saved_meal_items_position').on(t.savedMealId, t.position),
		check('saved_meal_items_kind_valid', sql`${t.kind} in ('food', 'quick')`),
		check(
			'saved_meal_items_shape',
			sql`(${t.kind} = 'food' and ${t.food} is not null and ${t.amount} > 0 and ${t.unit} is not null)
				or (${t.kind} = 'quick' and ${t.food} is null and ${t.amount} is null and ${t.unit} is null
					and ${t.foodId} is null and (${t.nutrients} -> 'energy_kcal') is not null)`
		),
		check(
			'saved_meal_items_description_length',
			sql`${t.description} is null or char_length(${t.description}) between 1 and 200`
		),
		check('saved_meal_items_nutrients_object', sql`jsonb_typeof(${t.nutrients}) = 'object'`),
		check('saved_meal_items_position_range', sql`${t.position} between 0 and 99`),
		index('saved_meal_items_user_idx').on(t.userId)
	]
);
